```cpp
#include <iostream>
#include <vector>

int customSequence(int n, std::vector<int>& memo) {
    if (n == 0) return 0;
    if (n == 1) return -1;
    if (n == 2) return -1;

    // 메모이제이션을 사용하여 이미 계산된 값을 반환
    if (memo[n] != -2) {
        return memo[n];
    }

    // 아직 계산되지 않은 경우, 재귀적으로 계산
    memo[n] = customSequence(n - 1, memo) + customSequence(n - 2, memo) + customSequence(n - 3, memo);
    return memo[n];
}

int main() {
    int n;
    std::cout << "수열의 몇 번째 항을 계산할까요? ";
    std::cin >> n;

    // 메모이제이션을 위한 벡터 초기화
    std::vector<int> memo(n + 1, -2); // -2는 아직 계산되지 않은 상태를 나타냄

    // 첫 세 숫자 초기화
    memo[0] = 0;
    memo[1] = -1;
    memo[2] = -1;

    int result = customSequence(n, memo);

    std::cout << n << "번째 항은 " << result << "입니다." << std::endl;

    return 0;
}
```

이 프로그램은 주어진 수열의 n번째 항을 계산합니다. `memo` 벡터를 사용하여 이미 계산된 값을 저장하고 재사용하여 계산 효율성을 높입니다. 첫 세 숫자는 직접 초기화하고, 그 이후의 항은 재귀적으로 계산됩니다. 이렇게 하면 큰 n에 대해서도 효율적으로 계산할 수 있습니다.

